// D'un EFFET au patron de la troupe de nœuds qu'il sème.
//
// Un effet procédural n'a aucun fichier : le client le dessine en code, et nous
// le portons nœud par nœud (docs/adr/0014). Cette table dit, pour les effets
// dont nous savons faire le dessin, quoi semer et comment.
//
// ⚠ ELLE EST COURTE, et c'est voulu. Le crible n'y laisse entrer que ce qui est
// COMPLET : un dessinateur porté et une ressource nommée. Une entrée sans
// ressource donnerait un nœud invisible — pire qu'une absence, puisqu'on
// croirait l'effet traité. Une vie non posée, en revanche, n'est pas une
// lacune : c'est celle que le constructeur du nœud donne.
//
// ⚠ UN EFFET Y PARAÎT PLUSIEURS FOIS, une par nœud qu'il sème. Les siens se
// suivent, ce qui permet de les rendre d'un seul span.
//
// ⚠ Fichier ENGENDRÉ par scripts/gen_client_effect_node_patterns.py depuis les
// relevés de scripts/, pas écrit à la main.

#include "ro/render/effect_node_pattern_table.h"

